INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66032175', 66032175, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'City Liaison Officers – SUSTAINABLE CITIES IMPACT PROJECT (GEF – SCIP)', 'Jasa Konsultansi', 'Seleksi', 'Sumatera Selatan, Palembang (Kota)', 192000000, 'February 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1', '1. Membantu PMU/PIU dalam pelaksanaan Proyek SCIP GEF Indonesia di tingkat kota; 2. Berperan sebagai penghubung (liaison) antara PMU, PIU, dan unsur pemerintah kota untuk memfasilitasi pemerintah kota dan pihak-pihak lain dalam memperoleh manfaat yang mendukung perencanaan terintegrasi, penyiapan sub-proyek, dan inovasi pendanaan di tingkat kota; 3. Mendorong komunikasi yang intensif dengan otoritas pemerintah kota, termasuk forum/sekretariat koordinasi pemerintah kota, Bappeda, perangkat daerah terkait, serta pemangku kepentingan lain yang terlibat dalam pelaksanaan kegiatan sub-komponen proyek; (sesuai KAK', '1. Pembaruan identifikasi pemangku kepentingan sebagai masukan dokumen SEP. 2. Dokumentasi kegiatan proyek (foto, daftar hadir, ringkasan kegiatan, catatan tindak lanjut). 3. Laporan insidental untuk dinamika proyek yang bersifat mendesak atau strategis. 4. Laporan Kemajuan (Progress Report) berkala yang merangkum seluruh aktivitas, isu teknis/safeguard, dan rekomendasi tindak lanjut.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2501205);
