INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66032067', 66032067, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Public Awareness and GRM Specialist – SUSTAINABLE CITIES IMPACT PROJECT (GEF – SCIP)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 280000000, 'February 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1', '1. Menjadi focal point untuk Grievance Mechanism di antara Bank Dunia, PMU, PIU, pemerintah daerah, kementerian terkait, serta pemangku kepentingan lainnya, seperti konsultan, komunitas, akademisi, dan organisasi non-pemerintah; 2. Bekerja secara erat dengan Environmental and Social Safeguard Specialist serta City Liaison Officers terkait untuk melaksanakan Stakeholder Engagement Plan (SEP), termasuk melakukan pemutakhiran bila diperlukan, serta memberikan nasihat kepada PIU dalam penyusunan dan pelaksanaan rencana aksi pelibatan pemangku kepentingan yang terkait dengan seluruh kegiatan SCIP; 3. Memastikan para pemangku kepentingan memperoleh informasi yang memadai, memitigasi berbagai kesalahpahaman yang mungkin tim (sesuai di KAK)', '1. Rencana kerja berbasis kinerja (output-based) yang jelas. 2. Dokumen kesadaran publik dan GRM yang telah diperbarui. 3. Materi pelatihan/kapasitas mengenai komunikasi dan GRM. 4. Laporan berkala (Progress Report) materi kesadaran dan analisis GRM. 5. Log keluhan (grievance log) yang diperbarui secara rutin sesuai standar Bank Dunia.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2501339);
