INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66032329', 66032329, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Analisis Peningkatan Kapasitas dan Pendampingan Praktis Pembiayaan Berkelanjutan di Lima Kota Percontohan Komponen 3 SCIP Tahun 2026', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 250000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Melakukan perumusan dan sinkronisasi rencana aksi strategis (action plan) tahunan yang mencakup tahap persiapan hingga pelaksanaan, serta memantau kemajuan persiapan agar sesuai rencana. Pemantauan mencakup proses pengadaan, kesiapan dokumen, koordinasi dengan pihak terkait, dan penyiapan logistik di tingkat pusat maupun daerah.', '1. Pendidikan minimal D-IV/S-1 di bidang Administrasi Bisnis/Manajemen, yang dibuktikan dengan ijazah; 2. memiliki pengalaman kerja minimal 4 tahun, dibuktikan dengan ijazah & surat keterangan kerja; 3. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik dilingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, yang dibuktikan dengan kontrak/surat keterangan kerja; 4. Pekerjaan sejenis di bidang menyusun dokumen administrasi proyek, yang dibuktikan dengan kontrak kerja/surat keterangan kerja; 5. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 6. Memiliki keterampilan organisasi, manajemen waktu, komunikasi, dan koordinasi lintas pemangku kepentingan (dibuktikan dengan surat keterangan kerja). 7. Memiliki kemampuan dalam melakukan penyiapan model bisnis proyek infrastruktur (dibuktikan dengan sertifikat). 8. Diutamakan Konsultan dalam negeri (dibuktikan dengan identitas kewarganegaan Indonesia seperti Kartu Tanda Penduduk; 9. Kemampuan berbahasa Inggris secara lisan dan tulisan (dibuktikan dengan sertifikat TOEFL/IELTS atau surat keterangan penggunaan bahasa Inggris di lingkungan kerja).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2501571);
