INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66032240', 66032240, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Project Integration Specialist – SUSTAINABLE CITIES IMPACT PROJECT (GEF – SCIP)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 30000000, 'March 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1', '1. Menyusun Metodologi Mid-Term Review (MTR). Konsultan wajib mengusulkan metodologi yang akan digunakan dalam pelaksanaan tinjauan dengan menerapkan pendekatan konsultatif dan partisipatif. Metodologi yang diusulkan harus secara memadai menjawab isu dan pertanyaan awal sebagaimana tercantum dalam Kerangka Acuan Kerja (ToR), dengan menguraikan isu tinjauan, pertanyaan kunci, metode pengumpulan data, serta metode analisis yang akan digunakan. Metodologi tersebut harus mencakup kombinasi metode kualitatif dan kuantitatif; 2. Melakukan analisis terhadap aspek manajemen proyek, termasuk kemajuan dalam pengelolaan keuangan, pengadaan, perlindungan lingkungan dan sosial, serta pencapaian Tujuan Pengembangan Proyek dan Indikator Hasil Antara (Project Development Objectives/Intermediate Results Indicators – PDOs/IRIs). Konsultan juga wajib menyajikan analisis komprehensif atas hasil proyek berdasarkan kriteria OECD-DAC, yang mencakup pertanyaan- (Sesuai KAK)', 'KELUARAN / DELIVERABLES 1. Metodologi Peninjauan Jangka Menengah (MTR). 2. Materi Survei (Kuesioner). 3. Materi Diskusi Kelompok Terfokus (FGD). 4. Laporan Pendahuluan (Inception Report). 5. Laporan Antara (Interim Report). 6. Laporan Akhir (Final Report).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2501576);
