INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66075195', 66075195, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN PENYUSUNAN KEBIJAKAN PUBLIK BIDANG INFRASTRUKTUR DALAM PELAKSANAAN SATGAS KEBENCANAAN DAN CAPACITY BUILDING', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 96800000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1', 'Mengumpulkan, mengolah, dan menyajikan data serta informasi terkait kejadian bencana, dampak terhadap infrastruktur, serta respons kebijakan yang relevan. Mengembangkan identifikasi isu, tantangan, dan pembelajaran kebijakan kebencanaan lintas sektor. Membantu pemantauan pelaksanaan tugas Satgas Kebencanaan dan penyusunan laporan perkembangan (progress report). Mendukung analisis keselarasan kebijakan kebencanaan dengan dokumen perencanaan pembangunan nasional dan sektor infrastruktur. Membantu penyusunan bahan evaluasi dan rekomendasi perbaikan tata kelola kebencanaan infrastruktur.', '1. Melakukan pengumpulan data dan informasi internal terkait perencanaan, koordinasi, dan manajemen Deputi. 2. Menganalisis isu-isu kebijakan, bottleneck implementasi, dan kebutuhan penguatan tata kelola internal. 3. Menyusun policy brief, executive summary, position paper, atau dokumen kebijakan lain yang diperlukan. 4. Mengelola sistem dokumentasi internal (arsip digital, klasifikasi dokumen, rekap tindak lanjut rapat). 5. Menyusun materi rapat, notulensi, dan laporan tindak lanjut. 6. Menyusun laporan bulanan, triwulan, serta laporan akhir kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2501760);
