INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66032022', 66032022, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Environmental and Social Safeguard Specialist – SUSTAINABLE CITIES IMPACT PROJECT (GEF – SCIP)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 280000000, 'February 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1', '1. Menjadi focal point untuk pengelolaan risiko lingkungan dan sosial terkait Proyek, termasuk dalam memelihara komunikasi antara Bank Dunia, PMU, PIU, pemerintah daerah, kementerian terkait, dan para pemangku kepentingan lainnya, seperti konsultan, komunitas, akademisi, serta organisasi non-pemerintah; 2. Memberikan nasihat kepada PMU dan PIU mengenai pengelolaan dampak dan risiko lingkungan dan sosial yang terkait dengan kegiatan SCIP, termasuk identifikasi dampak dan risiko lingkungan dan sosial serta penyusunan dan penerapan langkah-langkah pengelolaannya. Hal ini mencakup pemberian bantuan teknis dalam penyusunan Terms of Reference (ToR) bagi konsultan dan kegiatan proyek, termasuk kegiatan capacity building dan bantuan teknis lainnya, dengan memastikan keselarasan dengan ESS (Lengkap di KAK)', 'KELUARAN ATAU HASIL KERJA KONSULTAN 1. Rencana kerja berbasis kinerja (output-based) yang jelas. 2. Materi peningkatan kapasitas dan pelatihan pengamanan lingkungan dan sosial. 3. Laporan analitis pengamanan lingkungan dan sosial untuk PMU. 4. Laporan Semesteran (kemajuan E&S berkala) untuk disampaikan ke Bank Dunia. 5. Pembaruan dokumen pengamanan berdasarkan rekomendasi Bank Dunia dan PMU.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2503273);
