INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66075300', 66075300, 'analyze_legacy', 'Kota Tangerang Selatan', 'kabkota', 'DINAS PARIWISATA', 'Belanja Jasa Tenaga Kesenian dan Kebudayaan', 'Jasa Lainnya', 'Dikecualikan', 'Banten, Tangerang Selatan (Kota)', 75000000, 'January 2026', 'APBD', 1, 1, '15 event/Penampilan', 'Jasa Lainnya, Belanja Pengisi Acara (Tingkat Kota); Tarian/Kebudayaan: 1. Menampilkan tarian sesuai konsep acara (tari penyambutan, tari daerah, tari kreasi). 2. Mengikuti gladi bersih dan technical meeting sebelum acara. 3. Hadir minimal 1–2 jam sebelum acara dimulai. 4. Menggunakan kostum, properti, dan make-up sesuai tema. 5. Menjaga sikap profesional selama acara berlangsung. 6. Berkoordinasi dengan EO, MC, dan tim produksi (sound system ). Seni Budaya Lainnya: 1. Menampilkan atraksi Seni Budaya sesuai konsep (demo jurus, pertunjukan kolosal, palang pintu). 2. Mengikuti gladi bersih dan koordinasi teknis. 3. Hadir lebih awal untuk pemanasan dan persiapan kostum. 4. Menyesuaikan gerakan dengan musik atau narasi MC. 5. Menjaga keamanan selama atraksi (tanpa kontak berbahaya). 6. Mendukung prosesi penyambutan tamu VIP jika diperlukan.', 'Seni Tari: 1. Jumlah penari: 3–7 orang (menyesuaikan konsep). 2. Durasi tampil: ±5–10 menit per sesi. 3. Kostum: Busana adat/kreasi lengkap dengan aksesoris. 4. Properti: Selendang, kipas, payung, atau properti khas daerah. 5. Musik: File MP3/Live musik (ditentukan panitia). 6. Latihan: Minimal 2–3 kali latihan sebelum hari H. Seni Budaya Lainnya : 1. Jumlah personel: 2–10 orang (tergantung konsep). 2. Durasi tampil: ±7–15 menit. 3. Kostum: Seragam seragam Budaya. 4. Properti: Golok replika/tongkat dll (aman & tidak tajam). 5. Musik pengiring: Musik tradisional Betawi/daerah (opsional). 6. Latihan: Minimal 2–3 kali sebelum tampil. 7. Keamanan: Wajib memastikan atraksi aman & terkendali.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2503658);
