INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66031999', 66031999, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Junior Procurement Officer SUSTAINABLE CITIES IMPACT PROJECT (GEF – SCIP)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 216000000, 'February 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1', 'RUANG LINGKUP LAYANAN Konsultan akan memfasilitasi dan mengawasi kemajuan pengadaan Proyek agar memenuhi kebijakan pengadaan dan kepatuhan regulasi Pemerintah Indonesia serta Bank Dunia. Tanggung jawab spesifik meliputi: 1. Membantu PMU dan PIU dalam penyusunan (atau pembaruan) dokumen Project’s Procurement Strategy for Development (PPSD) dan Rencana Pengadaan (Procurement Plan). 2. Memantau kemajuan pengadaan dan mengelola seluruh aspek pengadaan Proyek menggunakan sistem Bank Dunia: Systematic Tracking of Exchanges in Procurement (STEP). 3. Membantu pembaruan data pengadaan secara bulanan, termasuk jadwal kegiatan, notifikasi kontrak, penetapan pemenang, dan manajemen kontrak pada sistem STEP. 4. Membantu pengembangan indikator kunci pengadaan untuk memastikan rencana pengadaan mencapai target. 5. Membantu dokumentasi dan persiapan aspek teknis pengadaan (TOR, Pengumuman Pengadaan, Dokumen Pengadaan, Laporan Evaluasi, permintaan No Objection Letter, dll). (Lengkap di KAK)', 'KUALIFIKASI KONSULTAN 1. Lulusan Sarjana (S1) di bidang yang relevan (seperti Teknik, Hukum, Keuangan, Hubungan Internasional, Administrasi, dll). 2. Pengalaman minimal 3 (tiga) tahun dalam manajemen/administrasi proyek atau kegiatan pemerintah di bidang pembangunan berkelanjutan, perubahan iklim, kehutanan, keanekaragaman hayati, atau administrasi pemerintahan. 3. Diutamakan memiliki pengalaman dengan sistem pengadaan Bank Dunia dan familiar dengan operasional teknis STEP. 4. Mampu menjembatani para pemangku kepentingan pengadaan dan bekerja secara dinamis dalam kelompok proyek. 5. Mampu menetapkan prioritas, bekerja dengan pengawasan minimal, dan memenuhi tenggat waktu. 6. Mahir menggunakan aplikasi perkantoran (MS Word, Excel, PowerPoint). 7. Fasih berbahasa Indonesia dan Inggris (lisan dan tulisan). 8. Pengalaman dalam proyek donor internasional atau proyek GEF-SCIP akan menjadi nilai tambah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2504299);
