INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66032232', 66032232, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Project Evaluation Specialist-SUSTAINABLE CITIES IMPACT PROJECT (GEF – SCIP)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 30000000, 'March 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1', '1. Menyusun Metodologi Mid-Term Review (MTR). Konsultan harus mengusulkan metodologi yang akan digunakan untuk melaksanakan tinjauan dengan pendekatan konsultatif dan partisipatif. Metodologi yang diusulkan harus secara memadai menjawab isu dan pertanyaan awal sebagaimana diuraikan dalam Kerangka Acuan Kerja (ToR), dengan menjelaskan isu tinjauan, pertanyaan kunci, metode pengumpulan data, serta metode analisis yang akan digunakan. Metodologi tersebut harus mencakup kombinasi metode kualitatif dan kuantitatif; 2. Melakukan analisis terhadap aspek manajemen proyek, termasuk kemajuan dalam pengelolaan keuangan, pengadaan, perlindungan lingkungan dan sosial, serta capaian Tujuan Pengembangan Proyek/Indikator Hasil Antara (Project Development Objectives/Intermediate Result Indicators – PDOs/IRIs). Konsultan juga harus menyajikan analisis komprehensif terhadap hasil proyek berdasarkan kriteria OECD-DAC, yang mencakup pertanyaan-pertanyaan kunci berikut: a. Relevansi: (Sesuai KAK)', '1. Metodologi Mid Term Review. 2. Materi Survei (Kuesioner). 3. Materi Focus Group Discussion (FGD). 4. Inception Report (Laporan Pendahuluan). 5. Interim Report (Laporan Antara). 6. Final Report (Laporan Akhir).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2504387);
