INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66029914', 66029914, 'analyze_legacy', 'Kab. Pelalawan', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'Paket 17 ( Tujuh Belas ) Pemasangan Plafon dan Keramik Gereja GKPI Desa Segati Kec. Langgam', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Riau, Pelalawan (Kab.)', 120600000, 'March 2026', 'APBD', 1, 1, '22.5 M2', 'Paket 17 ( Tujuh Belas ) Pemasangan Plafon dan Keramik Gereja GKPI Desa Segati Kec. Langgam', 'Paket 17 ( Tujuh Belas ) Pemasangan Plafon dan Keramik Gereja GKPI Desa Segati Kec. Langgam', 120600000, 'high', 'Penggunaan anggaran daerah melalui perangkat pekerjaan umum untuk renovasi fasilitas rumah ibadah tertentu berindikasi tidak selaras dengan fungsi belanja infrastruktur publik yang netral dan berpotensi menimbulkan persoalan kepatutan penggunaan APBD. Dari judul pekerjaan, manfaatnya tampak spesifik untuk institusi keagamaan tertentu, sehingga seluruh nilai patut dicermati sebagai potensi pemborosan atau pengeluaran yang tidak tepat sasaran.', NULL, NULL, 3, 1, 1, 1, 1, 2504769);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66074841', 66074841, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Peralatan Kantor Berupa Pekerjaan Peralatan Kantor Meja kayu/Set Meja Rapat Bundar Pada Ruang Dirjen KI Direktorat Jenderal Kekayaan Intelektual DKI Jakarta T.A 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 150000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Kelengkapan peralatan kantor serta keindahan pada suatu ruang atau ruang kerja pimpinan sangat mempengaruhi semangat dan dapat meningkatkan rasa nyaman serta tetap fokus dalam melaksanakan tugas dalam pekerjaan. Ruang kerja pimpinan bukan sekadar tempat menjalankan tugas administratif, melainkan pusat pengambilan keputusan strategis dan representasi citra institusi. Diperlukan penataan ruang yang mampu menyeimbangkan fungsionalitas tinggi, kenyamanan (ergonomi) untuk mendukung stamina kerja, serta estetika yang mencerminkan profesionalisme dan kewibawaan organisasi. Maka dipandang perlu adanya Pengadaan Peralatan Kantor berupa pekerjaan Peralatan Kantor Meja kayu/Set Meja Rapat Bundar Ruang Dirjen KI. Kegiatan tersebut sangat perlu dilakukan untuk kelengkapan serta peralatan sarana dan prasarana di ruang tersebut', '1. Meja Rapat bulat diameter 200 cm terbuat dari bahan kayu jati tebal 4-5 cm (1 Unit) 2. Kursi Rapat Dankha SFK Ukuran : P.55 X L.50 X T.100-114 CM (10 Unit)', 90000000, 'high', 'Pengadaan furnitur untuk ruang pimpinan dengan spesifikasi premium, khususnya meja rapat bulat dari kayu jati tebal 4–5 cm, berindikasi berorientasi pada estetika/prestise dibanding kebutuhan fungsional dasar kantor. Nilai anggaran 1 paket tampak tinggi untuk satu set meja rapat dan 10 kursi, sehingga layak diduga mengandung komponen kemewahan atau spesifikasi berlebihan yang berpotensi menimbulkan pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 2504770);
