INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66081216', 66081216, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Junior Penyusunan Pedoman Penguatan Proses Asesmen dan Pelaksanaan Program Kartu Usaha Afirmatif (KUA)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 63000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Mendukung dan mengawal pelaksanaan proses asesmen peserta Program KUA secara sistematis dan berbasis data, meliputi pemetaan kondisi sosial ekonomi, potensi, minat, dan kebutuhan intervensi masyarakat miskin dan rentan desil 1–4, sebagai dasar penentuan penempatan peserta yang tepat sasaran pada skema Kesempatan Bekerja atau Kesempatan Berwirausaha. 2. Melakukan analisis hasil asesmen dan penajaman rekomendasi intervensi, dengan memastikan kesesuaian antara profil peserta, tingkat kesiapan, dan jenis intervensi yang akan diberikan, sehingga desain intervensi yang disusun bersifat realistis, adaptif terhadap kondisi lapangan, dan memiliki peluang keberhasilan yang tinggi. 3. Memberikan dukungan teknis dalam pelaksanaan intervensi Program KUA, termasuk penajaman desain pelatihan, penguatan metode pendampingan kerja dan/atau usaha, serta pengawalan tahapan implementasi intervensi agar berjalan konsisten dengan hasil asesmen dan tujuan program. 4. Memfasilitasi keterhubungan peserta dengan ekosistem pendukung kerja dan usaha, melalui koordinasi dengan dunia usaha, lembaga pelatihan, lembaga keuangan, dan pemangku kepentingan terkait, guna membuka akses terhadap peluang kerja, usaha, pasar, dan pembiayaan yang mendukung keberlanjutan hasil intervensi. 5. Melakukan pemantauan progres pelaksanaan dan perkembangan peserta secara berkala, melalui pengumpulan dan analisis data lapangan, untuk menilai capaian', '1. Mendukung dan mengawal pelaksanaan proses asesmen peserta Program KUA secara sistematis dan berbasis data, meliputi pemetaan kondisi sosial ekonomi, potensi, minat, dan kebutuhan intervensi masyarakat miskin dan rentan desil 1–4, sebagai dasar penentuan penempatan peserta yang tepat sasaran pada skema Kesempatan Bekerja atau Kesempatan Berwirausaha. 2. Melakukan analisis hasil asesmen dan penajaman rekomendasi intervensi, dengan memastikan kesesuaian antara profil peserta, tingkat kesiapan, dan jenis intervensi yang akan diberikan, sehingga desain intervensi yang disusun bersifat realistis, adaptif terhadap kondisi lapangan, dan memiliki peluang keberhasilan yang tinggi. 3. Memberikan dukungan teknis dalam pelaksanaan intervensi Program KUA, termasuk penajaman desain pelatihan, penguatan metode pendampingan kerja dan/atau usaha, serta pengawalan tahapan implementasi intervensi agar berjalan konsisten dengan hasil asesmen dan tujuan program. 4. Memfasilitasi keterhubungan peserta dengan ekosistem pendukung kerja dan usaha, melalui koordinasi dengan dunia usaha, lembaga pelatihan, lembaga keuangan, dan pemangku kepentingan terkait, guna membuka akses terhadap peluang kerja, usaha, pasar, dan pembiayaan yang mendukung keberlanjutan hasil intervensi. 5. Melakukan pemantauan progres pelaksanaan dan perkembangan peserta secara berkala, melalui pengumpulan dan analisis data lapangan, untuk menilai capaian', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2509901);
