INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66079449', 66079449, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'IM16 KANTOR IMIGRASI KELAS I TPI SINGKAWANG', 'PENGADAAN SEWA SAFE HOUSE DAN SEWA TRANSPORTASI KHUSUS DALAM RANGKA OPERASI PADA KANTOR IMIGRASI KELAS I TPI SINGKAWANG - PROVINSI KALIMANTAN BARAT TAHUN ANGGARAN 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kalimantan Barat, Singkawang (Kota)', 42000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '4 Kegiatan', '1. Safe House ( 4, keg, @ 3000000 ); 2. Sewa Transportasi Khusus dalam Rangka Operasi ( 4, keg, @ 7500000 ); Belanja Sewa 6161.BHB.U12.051.0A.522141 digunakan untuk penyediaan safe house dan transportasi khusus guna mendukung pelaksanaan operasi pengawasan dan penegakan hukum keimigrasian secara aman, efektif, dan sesuai kebutuhan operasional di lapangan.', 'SPESIFIKASI PEKERJAAN A. Spesifikasi Sewa Safe House Jenis Bangunan Rumah tinggal/guest house/ruko yang layak huni. Struktur bangunan permanen dan aman. Tidak berada di lokasi rawan gangguan keamanan. Kapasitas dan Fasilitas Minimal 2–3 kamar tidur. 1 ruang tamu/ruang serbaguna. Kamar mandi dan sanitasi layak. Instalasi listrik dan air berfungsi baik. Ventilasi dan pencahayaan memadai. Keamanan Memiliki pagar atau sistem pengamanan dasar. Lingkungan relatif kondusif dan tidak mencolok. Dapat menjamin aspek kerahasiaan kegiatan operasi. Durasi Sewa Harian/bulanan sesuai kebutuhan operasi. Fleksibel mengikuti jadwal kegiatan lapangan. Status Tidak menimbulkan hak kepemilikan. Bersifat sewa murni (tidak menjadi aset negara). B. Spesifikasi Sewa Transportasi Khusus Operasi Jenis Kendaraan Roda empat (minibus/SUV/double cabin) sesuai kebutuhan operasi. Kondisi laik jalan dan usia kendaraan wajar. Kapasitas sesuai jumlah personel operasi. Kelengkapan Surat kendaraan lengkap dan aktif. Asuransi (jika tersedia). Dapat termasuk pengemudi (jika dibutuhkan). Kondisi Teknis Mesin, rem, lampu, dan sistem keselamatan berfungsi baik. Interior bersih dan layak digunakan. Durasi Sewa Harian atau paket sesuai kebutuhan operasi. Fleksibel mengikuti jadwal kegiatan lapangan. Ketentuan Pembayaran Dibayar sesuai durasi pemakaian. Tidak menambah aset negara.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2509955);
